#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# All gh/git options below were checked against this VM's command help.
# No credentials are captured or persisted by these stages.
fail() { warn "$1"; exit 1; }

# Only a confirmed missing release is treated as absent; API/auth errors stop.
read_release() {
  if gh release view "$TAG" --json isDraft,assets,url > "$WORK/release.json" 2> "$WORK/release-error"; then
    return 0
  fi
  if grep -Eq 'release not found|HTTP 404' "$WORK/release-error"; then
    return 2
  fi
  cat "$WORK/release-error" >&2
  return 1
}

rollback() {
  local state remote_tag rc=0
  if read_release; then
    state=$(node -p 'JSON.parse(require("fs").readFileSync(process.argv[1])).isDraft' "$WORK/release.json")
    if [[ "$state" != true ]]; then
      warn "The release is published. Keep its tags and assets."
      if confirm "Unpublish $TAG by returning it to draft?"; then
        gh release edit "$TAG" --draft=true || warn "Unpublish failed; inspect the release on GitHub."
      fi
      return 0
    fi
    if confirm "Delete the draft release $TAG?"; then
      gh release delete "$TAG" --yes || { warn "Draft deletion failed; tags were kept."; return 0; }
    else
      warn "Draft kept; tags were kept too."
      return 0
    fi
  else
    rc=$?
    if [[ "$rc" != 2 ]]; then
      warn "Could not determine release state; inspect GitHub before any rollback. Tags were kept."
      return 0
    fi
  fi
  warn "Ensure the release workflow is finished before deleting tags."
  if remote_tag=$(git ls-remote --tags origin "refs/tags/$TAG"); then
    if [[ -n "$remote_tag" ]] && confirm "Delete remote tag $TAG?"; then
      git push --delete origin "$TAG" || warn "Remote tag deletion failed; inspect origin tags."
    fi
  else
    warn "Could not check origin tags; inspect origin before deleting the remote tag."
  fi
  if [[ -n "$(git tag --list "$TAG")" ]] && confirm "Delete local tag $TAG?"; then
    git tag -d "$TAG" || warn "Local tag deletion failed; inspect git tags."
  fi
}

# Prints the assets and enforces the three expected formats before publication.
check_assets() {
  node - "$WORK/release.json" "$1" <<'JS'
const fs = require('fs');
const release = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const expectedDraft = process.argv[3] === 'true';
console.log(`Draft: ${release.isDraft}`);
for (const asset of release.assets) console.log(`${asset.name} (${asset.size} bytes)`);
const extensions = release.assets.map(asset => asset.name.split('.').pop()).sort();
if (release.isDraft !== expectedDraft || JSON.stringify(extensions) !== '["deb","rpm","zip"]') {
  console.error('Expected draft state and exactly one .deb, .rpm and .zip asset.');
  process.exit(1);
}
if (!expectedDraft) console.log(`Release URL: ${release.url}`);
JS
}

run_wizard() {
TOTAL_STAGES=6
banner "Publish Pocket Notebook"

stage "Preconditions"
for tool in gh git node; do
  command -v "$tool" >/dev/null 2>&1 || fail "Install $tool before continuing."
done
gh auth status || fail "Authenticate with gh before continuing."
[[ "$(git branch --show-current)" == main ]] || fail "Run this wizard from main."
[[ -f package.json && -f .github/workflows/release.yml ]] || fail "Run from the repository root."
[[ -z "$(git status --porcelain)" ]] || fail "Working tree must be clean, including untracked files."
git fetch origin || fail "Fetching origin failed."
HEAD_SHA=$(git rev-parse HEAD)
[[ "$HEAD_SHA" == "$(git rev-parse origin/main)" ]] || fail "HEAD must equal origin/main. Update main first."
VERSION=$(node -p 'require("./package.json").version')
[[ "$VERSION" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]] || fail "Expected a stable numeric package version."
TAG="v$VERSION"
[[ -z "$(git tag --list "$TAG")" ]] || fail "Local tag $TAG already exists."
REMOTE_TAG=$(git ls-remote --tags origin "refs/tags/$TAG") || fail "Could not check origin tags."
[[ -z "$REMOTE_TAG" ]] || fail "Origin tag $TAG already exists."
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT
NOTES_FILE="$WORK/notes.md"
if read_release; then
  fail "GitHub release $TAG already exists."
else
  rc=$?
  [[ "$rc" == 2 ]] || fail "Could not check whether the GitHub release exists."
fi
gh run list --workflow proof.yml --branch main --commit "$HEAD_SHA" --limit 1 \
  --json conclusion,status > "$WORK/proof.json" || fail "Could not read Proof runs."
node - "$WORK/proof.json" <<'JS' || fail "The latest Proof run for this main commit must be completed and successful."
const runs = JSON.parse(require('fs').readFileSync(process.argv[2], 'utf8'));
process.exit(runs.length === 1 && runs[0].status === 'completed' && runs[0].conclusion === 'success' ? 0 : 1);
JS
say "Ready: $TAG at $HEAD_SHA; Proof succeeded."
pause

stage "Release notes"
cat > "$NOTES_FILE" <<NOTES
Pocket Notebook $VERSION is the first release.

- Browse, create, edit, and delete notes with a title and body.
- Notes are stored only on your device; no accounts, servers, analytics, or cloud sync.
- An About view explains how the notebook works.

Downloads: Linux x64 (.deb, .rpm) and macOS Apple silicon (.zip). Windows is not available in this release.

These packages are not code-signed. On macOS, Gatekeeper warns on first launch; open the app with right-click > Open.
NOTES
say "These public notes are your message to users. Keep the default or edit it."
if confirm "Edit the release notes with ${EDITOR:-nano}?"; then
  # Support EDITOR with arguments without evaluating shell code.
  read -r -a editor_command <<< "${EDITOR:-nano}"
  "${editor_command[@]}" "$NOTES_FILE" || fail "Editor failed; no tag has been pushed."
fi
[[ -s "$NOTES_FILE" ]] || fail "Release notes must not be empty."
cat "$NOTES_FILE"
pause "Review the final notes, then press Enter."

stage "Push the tag"
say "Tag: $TAG"
say "Commit: $HEAD_SHA"
confirm "Create and push this annotated tag, starting the release workflow?" || fail "Cancelled before tag creation."
[[ "$(git rev-parse HEAD)" == "$HEAD_SHA" && -z "$(git status --porcelain)" ]] || fail "Checkout changed; restart the wizard."
git tag -a "$TAG" -m "Pocket Notebook $VERSION" "$HEAD_SHA" || fail "Tag creation failed."
if ! git push origin "$TAG"; then
  rollback
  fail "Tag push failed; inspect origin before trying again."
fi
REMOTE_TAG=$(git ls-remote --tags origin "refs/tags/$TAG^{}") || { rollback; fail "Could not verify origin tag."; }
[[ "${REMOTE_TAG%%[[:space:]]*}" == "$HEAD_SHA" ]] || { rollback; fail "Origin tag does not point to the intended commit."; }

stage "Wait for the release workflow"
say "The workflow builds packages and creates only a draft release."
while true; do
  if ! gh run list --workflow release.yml --branch "$TAG" --commit "$HEAD_SHA" \
    --event push --limit 1 --json databaseId > "$WORK/run.json"; then
    rollback
    fail "Could not locate the release workflow."
  fi
  RUN_ID=$(node -p 'JSON.parse(require("fs").readFileSync(process.argv[1]))[0]?.databaseId || ""' "$WORK/run.json")
  [[ -n "$RUN_ID" ]] && break
  say "The tag run is not visible yet. Wait a moment before retrying."
  if ! confirm "Check for the workflow run again?"; then
    warn "A workflow may still start. Wait for it to finish on GitHub before rollback."
    fail "Stopped waiting; tag kept. Resume by inspecting the run and draft manually."
  fi
done
if ! gh run watch "$RUN_ID" --exit-status; then
  warn "Workflow failed, or its status could not be read. Ensure it has finished before rollback."
  rollback
  fail "Release workflow did not succeed."
fi

stage "Review and publish"
say "Final public release notes:"
cat "$NOTES_FILE"
if ! read_release || ! check_assets true; then
  rollback
  fail "Expected a draft release with all three packages."
fi
say "Packages are unsigned. macOS Gatekeeper warns; Windows is not provided."
confirm "Publish $TAG with these notes and files?" || fail "Publication cancelled; the draft and tags remain on GitHub."
if ! gh release edit "$TAG" --notes-file "$NOTES_FILE" --draft=false; then
  rollback
  fail "Publishing failed; inspect the release state."
fi

stage "Verify"
if ! read_release || ! check_assets false; then
  rollback
  fail "Published release verification failed."
fi
say "Packages are unsigned. On macOS, right-click > Open or remove quarantine if Gatekeeper blocks launch."
say "Windows is not provided."
if confirm "Unpublish this release by returning it to draft?"; then
  gh release edit "$TAG" --draft=true || fail "Unpublish failed; inspect the release on GitHub."
  say "Release returned to draft; tags and assets kept."
fi
finish
}

run_wizard "$@"; exit
